const MAX_FILE_BYTES=25*1024*1024;
const readRoles=new Set<UserRole>([UserRole.ADMINISTRATOR,UserRole.PROGRAM_MANAGER,UserRole.AUDITOR,UserRole.RN,UserRole.LPN,UserRole.DELEGATING_NURSE,UserRole.HOUSE_MANAGER,UserRole.ADMINISTRATIVE_ASSISTANT,UserRole.CEO,UserRole.DOO]);
const writeRoles=new Set<UserRole>([UserRole.ADMINISTRATOR,UserRole.PROGRAM_MANAGER,UserRole.RN,UserRole.LPN,UserRole.DELEGATING_NURSE,UserRole.HOUSE_MANAGER,UserRole.ADMINISTRATIVE_ASSISTANT,UserRole.CEO,UserRole.DOO]);
const reviewRoles=new Set<UserRole>([UserRole.ADMINISTRATOR,UserRole.PROGRAM_MANAGER,UserRole.RN,UserRole.DELEGATING_NURSE,UserRole.CEO,UserRole.DOO]);
const httpError=(status:number,message:string,details?:unknown)=>Object.assign(new Error(message),{status,details});
const selectedEntity=(a:AuthContext)=>{if(!a.legalEntityId)throw httpError(409,'Select a Sulandra company before opening Client Intake');return a.legalEntityId;};
const owner=(a:AuthContext)=>a.enterpriseOwner===true||String(a.email||'').trim().toLowerCase()==='admin@sulandrahealth.com';
const ensureRead=(a:AuthContext)=>{if(!readRoles.has(a.role)&&!owner(a))throw httpError(403,'Client intake access is required');selectedEntity(a);};
const ensureWrite=(a:AuthContext)=>{ensureRead(a);if(a.role===UserRole.AUDITOR||(!writeRoles.has(a.role)&&!owner(a)))throw httpError(403,'Your client intake access is read-only');};
const ensureReview=(a:AuthContext)=>{ensureWrite(a);if(!reviewRoles.has(a.role)&&!owner(a))throw httpError(403,'Clinical or program intake review permission is required');};
const clean=(v:unknown,max=5000)=>typeof v==='string'?v.trim().slice(0,max):'';
const safeDate=(v:unknown)=>{const s=clean(v,20);return s?/^\d{4}-\d{2}-\d{2}$/.test(s)?s:null:null;};
const safeFileName=(v:string)=>v.replace(/[\r\n"]/g,'_').replace(/[\\/]/g,'_').slice(0,300)||'document';
const jsonObject=(v:unknown):Record<string,unknown>=>v&&typeof v==='object'&&!Array.isArray(v)?v as Record<string,unknown>:{};
const jsonArray=(v:unknown):unknown[]=>Array.isArray(v)?v:[];

